sys_script_include.script:
var AESAgentChatRouting = Class.create();
AESAgentChatRouting.prototype = {

    matchesRoute: function(current, routingKey) {
        if (!current || !routingKey)
            return false;

        var contextTable = current.getValue('context_table');
        var contextDocument = current.getValue('context_document');

        if (!contextTable || !contextDocument)
            return false;

        var contextGR = new GlideRecord(contextTable);

        if (!contextGR.get(contextDocument))
            return false;

        try {
            var context = JSON.parse(
                contextGR.getValue('value') || '{}'
            );

            return context.liveagent_aes_route === routingKey;

        } catch (e) {
            return false;
        }
    },

    type: 'AESAgentChatRouting'
};
